// node tools/verify-lifecycle-history.mjs [artifact-directory]
// Failure modes: wrong/missing ref, current assets used for historical init,
// generated layout/schema/mode misreported, check-only writes, migration loses
// project data or leaves an unusable project, unavailable historical tooling
// presented as coverage. Every project is generated by its archived CLI.
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { createHash } from "node:crypto";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const repo = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const artifacts = path.resolve(process.argv[2] ?? process.env.SPECTRA_HISTORY_ARTIFACT_DIR ?? path.join(os.tmpdir(), "spectra-lifecycle-history"));
fs.mkdirSync(artifacts, { recursive: true });
const runRoot = fs.mkdtempSync(path.join(os.tmpdir(), "spectra-history-run-"));
const refs = ["v2.0.3", "13287b4", "v3.0.8", "v3.0.9", "v3.1.0", "v3.1.1", "v3.1.2"];
const report = { current: {}, projects: [], passed: false };
const sha256 = value => createHash("sha256").update(value).digest("hex");
const hashFile = file => sha256(fs.readFileSync(file));
function run(command, args, cwd, env = {}) {
  const result = spawnSync(command, args, { cwd, env: { ...process.env, ...env }, encoding: "utf8", maxBuffer: 20 * 1024 * 1024 });
  return { command: [command, ...args], cwd: path.relative(runRoot, cwd) || ".", exitCode: result.status, stdout: result.stdout, stderr: result.stderr, error: result.error?.message };
}
function inventory(root, prefix = "") {
  return fs.readdirSync(root, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name)).flatMap(entry => {
    const relative = path.posix.join(prefix, entry.name);
    const file = path.join(root, entry.name);
    if (entry.isSymbolicLink()) return [[relative, `symlink:${fs.readlinkSync(file)}`]];
    return entry.isDirectory() ? inventory(file, relative) : [[relative, hashFile(file)]];
  });
}
const treeHash = root => sha256(JSON.stringify(inventory(root)));
function fileEnding(root, suffix) {
  return inventory(root).find(([name]) => name === suffix || name.endsWith(`/${suffix}`))?.[0];
}
function generatedState(root) {
  const manifest = [".spectra/sdd/system/manifest.env", "spectra/sdd/system/manifest.env", "sdd/system/manifest.env"].find(file => fs.existsSync(path.join(root, file)));
  const layout = manifest?.startsWith(".spectra/") ? "canonical" : manifest?.startsWith("spectra/") ? "spectra-dir" : manifest ? "root-sdd" : null;
  const metadataPath = [".spectra/install.json", "spectra/install.json"].find(file => fs.existsSync(path.join(root, file)));
  const metadata = metadataPath ? JSON.parse(fs.readFileSync(path.join(root, metadataPath), "utf8")) : {};
  const configPath = [".spectra/config.yaml", "spectra/config.yaml"].find(file => fs.existsSync(path.join(root, file)));
  const config = configPath ? fs.readFileSync(path.join(root, configPath), "utf8") : "";
  const schemaMatch = config.match(/^schemaVersion:\s*(\d+)\s*$/m);
  const gitMatch = config.match(/^gitMode:\s*([^\s]+)\s*$/m);
  return {
    layout,
    schemaVersion: metadata.schemaVersion ?? (schemaMatch ? Number(schemaMatch[1]) : null),
    gitMode: metadata.gitMode ?? gitMatch?.[1] ?? null,
    manifestPath: manifest,
    metadataPath,
    configPath
  };
}
function writeReport() {
  fs.writeFileSync(path.join(artifacts, "results.json"), `${JSON.stringify(report, null, 2)}\n`);
}

try {
  const head = run("git", ["rev-parse", "HEAD"], repo);
  assert.equal(head.exitCode, 0, head.stderr);
  const modified = run("git", ["status", "--short"], repo);
  report.current = {
    commit: head.stdout.trim(),
    version: JSON.parse(fs.readFileSync(path.join(repo, "package.json"), "utf8")).version,
    dirtyPaths: modified.stdout.split("\n").filter(Boolean),
    yamlDependencyVersion: JSON.parse(fs.readFileSync(path.join(repo, "node_modules/yaml/package.json"), "utf8")).version
  };
  for (const ref of refs) {
    const item = { ref, commands: [], passed: false };
    report.projects.push(item);
    try {
      const resolved = run("git", ["rev-parse", `${ref}^{commit}`], repo);
      assert.equal(resolved.exitCode, 0, `Unreachable source ref ${ref}: ${resolved.stderr}`);
      item.sourceSha = resolved.stdout.trim();
      item.sourceVersion = JSON.parse(run("git", ["show", `${ref}:package.json`], repo).stdout).version;
      const source = path.join(runRoot, "sources", item.sourceSha);
      const archive = path.join(runRoot, `${item.sourceSha}.tar`);
      fs.mkdirSync(source, { recursive: true });
      const archived = run("git", ["archive", "--format=tar", `--output=${archive}`, item.sourceSha], repo);
      item.commands.push(archived);
      assert.equal(archived.exitCode, 0, archived.stderr);
      item.sourceArchiveSha256 = hashFile(archive);
      const extracted = run("tar", ["-xf", archive, "-C", source], repo);
      item.commands.push(extracted);
      assert.equal(extracted.exitCode, 0, extracted.stderr);
      const cliRoot = path.join(source, "packages/cli");
      const cli = path.join(cliRoot, "bin/spectra.js");
      assert(fs.existsSync(cli), `Archived CLI missing at ${ref}`);
      const historicalNodeModules = path.join(cliRoot, "node_modules");
      fs.mkdirSync(path.dirname(historicalNodeModules), { recursive: true });
      fs.mkdirSync(historicalNodeModules, { recursive: true });
      fs.symlinkSync(path.join(repo, "node_modules/yaml"), path.join(historicalNodeModules, "yaml"), "dir");
      item.historicalDependency = { name: "yaml", version: report.current.yamlDependencyVersion, source: "existing workspace node_modules symlink; no install or network" };
      const syncAssets = path.join(cliRoot, "scripts/sync-assets.mjs");
      if (fs.existsSync(syncAssets)) {
        const synced = run(process.execPath, [syncAssets], source);
        item.commands.push(synced);
        assert.equal(synced.exitCode, 0, synced.stderr || synced.stdout);
      }
      item.archivedCliSha256 = hashFile(cli);
      const archivedAssets = path.join(cliRoot, "assets");
      item.archivedAssetsSha256 = fs.existsSync(archivedAssets) ? treeHash(archivedAssets) : null;
      const schemaSource = ["src/lib/install-metadata.js", "src/lib/profile.js"].map(file => path.join(cliRoot, file)).find(file => fs.existsSync(file));
      const schemaText = schemaSource ? fs.readFileSync(schemaSource, "utf8") : "";
      const schema = schemaText.match(/SCHEMA_VERSION\s*=\s*(\d+)/)?.[1];
      item.sourceSchemaVersion = schema ? Number(schema) : null;
      const project = path.join(runRoot, "projects", item.sourceSha);
      const initArgs = [cli, "init", project];
      if (item.sourceVersion !== "2.0.3") initArgs.push("--git-mode", "shared");
      const init = run(process.execPath, initArgs, source);
      item.commands.push(init);
      assert.equal(init.exitCode, 0, init.error || init.stderr || init.stdout);
      const before = generatedState(project);
      item.generated = { ...before, generationMode: before.gitMode ?? "shared (historical CLI default)" };
      assert(before.layout, `Historical init did not produce a recognizable project layout at ${ref}`);
      const protectedSuffixes = ["sdd/memory-bank/core/projectbrief.md", "sdd/governance/approval-state.yaml", "sdd/governance/decision-graph.yaml"];
      item.projectKeyFiles = Object.fromEntries(protectedSuffixes.map(suffix => [suffix, fileEnding(project, suffix)])
        .filter(([, file]) => file).map(([suffix, file]) => [suffix, hashFile(path.join(project, file))]));
      const sentinel = path.join(project, "historical-user-data.md");
      fs.writeFileSync(sentinel, `Generated from ${ref} (${item.sourceSha}).\n`);
      item.sentinelSha256 = hashFile(sentinel);
      item.projectKeyFiles["historical-user-data.md"] = item.sentinelSha256;
      const current = path.join(repo, "packages/cli/bin/spectra.js");
      const checkBefore = treeHash(project);
      const migrationCheck = run(process.execPath, [current, "migrate", "--cwd", project, "--check", "--json"], repo);
      item.commands.push(migrationCheck);
      const checkResult = JSON.parse(migrationCheck.stdout);
      assert(["migration-required", "current"].includes(checkResult.outcome), checkResult.reason ?? JSON.stringify(checkResult));
      assert.equal(migrationCheck.exitCode, checkResult.outcome === "current" ? 0 : 1);
      assert.equal(treeHash(project), checkBefore, "migrate --check changed the historical project");
      item.migrationCheck = { outcome: checkResult.outcome, steps: checkResult.steps?.map(step => step.id) ?? [], inventorySha256: checkBefore };
      if (checkResult.outcome === "migration-required") {
        const migrate = run(process.execPath, [current, "migrate", "--cwd", project, "--yes", "--json"], repo);
        item.commands.push(migrate);
        try { item.migration = JSON.parse(migrate.stdout); } catch {}
        const changed = Object.entries(item.projectKeyFiles).flatMap(([suffix, expected]) => {
          const file = suffix === "historical-user-data.md" ? suffix : fileEnding(project, suffix);
          const actual = file ? hashFile(path.join(project, file)) : null;
          return actual === expected ? [] : [{ suffix, expected, actual }];
        });
        item.projectKeyFileChanges = changed;
        assert.deepEqual(changed, [], "Historical project key files changed during migration");
        assert.equal(migrate.exitCode, 0, migrate.error || migrate.stderr || migrate.stdout);
      }
      item.finalState = generatedState(project);
      assert.equal(item.finalState.layout, "canonical", "Migration did not converge to canonical layout");
      assert.equal(item.finalState.schemaVersion, 3, "Migration did not converge to schema 3");
      assert.equal(hashFile(sentinel), item.sentinelSha256, "Migration changed historical user data");
      const settled = run(process.execPath, [current, "migrate", "--cwd", project, "--check", "--json"], repo);
      item.commands.push(settled);
      assert.equal(settled.exitCode, 0, settled.stderr || settled.stdout);
      assert.equal(JSON.parse(settled.stdout).outcome, "current");
      const version = run(process.execPath, [current, "version"], project);
      item.commands.push(version);
      assert.equal(version.exitCode, 0, version.error || version.stderr || version.stdout);
      const validation = run(process.execPath, [current, "check", "--cwd", project], repo);
      item.commands.push(validation);
      assert.equal(validation.exitCode, 0, validation.error || validation.stderr || validation.stdout);
      item.finalInventorySha256 = treeHash(project);
      item.finalFileCount = inventory(project).length;
      item.passed = true;
    } catch (error) {
      item.failure = { message: error.message, stack: error.stack };
      report.passed = false;
      writeReport();
    }
  }
  report.passed = report.projects.every(project => project.passed);
} catch (error) {
  report.failure = { message: error.message, stack: error.stack };
  report.passed = false;
} finally {
  report.artifactDirectory = artifacts;
  fs.rmSync(runRoot, { recursive: true, force: true });
  writeReport();
}
console.log(`${report.passed ? "Historical lifecycle E2E passed" : "Historical lifecycle E2E failed"}: ${path.join(artifacts, "results.json")}`);
if (!report.passed) process.exitCode = 1;
